-- Domain 09: Purchasing & Inventory | functions
-- Generated by tools/split_by_domain.py. Statements keep their original order tag (@seq).

-- @seq 357
CREATE FUNCTION public.apply_stock_movement(p_tenant_id uuid, p_inventory_item_id text, p_date date, p_type text, p_quantity numeric, p_unit_cost numeric DEFAULT 0, p_source text DEFAULT 'manual'::text, p_source_id text DEFAULT NULL::text, p_reference text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'lms', 'public', 'pg_catalog'
    AS $$
declare
  v_id           text;
  v_item         inventory_items%rowtype;
  v_new_qty      numeric(18,4);
  v_new_cost     numeric(18,4);
  v_total_cost   numeric(18,4);
begin
  select * into v_item from inventory_items
   where id = p_inventory_item_id and tenant_id = p_tenant_id;
  if not found then raise exception 'Inventory item not found'; end if;
  v_new_qty := v_item.quantity_on_hand + p_quantity;
  if v_new_qty < 0 then
    raise exception 'Insufficient stock for item % (current: %, requested: %)',
      v_item.sku, v_item.quantity_on_hand, abs(p_quantity);
  end if;
  if p_quantity > 0 and p_unit_cost > 0 then
    v_total_cost := (v_item.quantity_on_hand * coalesce(v_item.unit_cost, 0)) + (p_quantity * p_unit_cost);
    v_new_cost := case when v_new_qty > 0 then v_total_cost / v_new_qty else 0 end;
  else
    v_new_cost := coalesce(v_item.unit_cost, 0);
  end if;
  insert into inventory_transactions (
    tenant_id, inventory_item_id, transaction_type, quantity, unit_cost,
    reason, reference_number, notes, performed_by
  ) values (
    p_tenant_id, p_inventory_item_id, p_type, p_quantity, p_unit_cost,
    p_source, p_reference, p_notes, auth.uid()::text
  )
  returning id into v_id;
  update inventory_items
     set quantity_on_hand = v_new_qty,
         unit_cost = v_new_cost,
         updated_at = now()
   where id = p_inventory_item_id;
  return v_id;
end;
$$;

-- @seq 383
CREATE FUNCTION public.create_purchase_order(p_tenant_id uuid, p_number text, p_vendor_id text, p_issue_date date, p_expected_date date DEFAULT NULL::date, p_currency text DEFAULT 'USD'::text, p_items jsonb DEFAULT NULL::jsonb, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'lms', 'public', 'pg_catalog'
    AS $$
declare
  v_po_id      uuid;
  v_item       jsonb;
  v_subtotal   numeric(18,4) := 0;
  v_tax_total  numeric(18,4) := 0;
  v_total      numeric(18,4) := 0;
  v_line_amt   numeric(18,4);
  v_tax_rate   numeric(6,4);
begin
  if p_items is null or jsonb_array_length(p_items) = 0 then
    raise exception 'No purchase order items provided';
  end if;

  insert into purchase_orders (tenant_id, number, vendor_id, issue_date, expected_date, currency, status, notes)
  values (p_tenant_id, p_number, p_vendor_id, p_issue_date, p_expected_date, p_currency, 'draft', p_notes)
  returning id into v_po_id;

  for v_item in select jsonb_array_elements(p_items) loop
    v_line_amt := coalesce((v_item->>'quantity')::numeric, 1) * coalesce((v_item->>'unit_price')::numeric, 0)
                  - coalesce((v_item->>'discount')::numeric, 0);
    v_subtotal := v_subtotal + v_line_amt;

    v_tax_rate := 0;
    if v_item ? 'tax_id' and (v_item->>'tax_id') is not null then
      select rate into v_tax_rate from taxes where id = (v_item->>'tax_id')::uuid;
    end if;
    v_tax_total := v_tax_total + (v_line_amt * v_tax_rate);

    insert into purchase_order_items (purchase_order_id, product_id, inventory_item_id, account_id, tax_id,
                                       description, quantity, unit_price, discount, position)
    values (v_po_id,
            nullif(v_item->>'product_id','')::text,
            nullif(v_item->>'inventory_item_id','')::text,
            (v_item->>'account_id')::uuid,
            nullif(v_item->>'tax_id','')::uuid,
            v_item->>'description',
            coalesce((v_item->>'quantity')::numeric, 1),
            coalesce((v_item->>'unit_price')::numeric, 0),
            coalesce((v_item->>'discount')::numeric, 0),
            coalesce((v_item->>'position')::int, 0));
  end loop;

  v_total := v_subtotal + v_tax_total;
  update purchase_orders set subtotal = v_subtotal, tax_total = v_tax_total, total = v_total
   where id = v_po_id;

  return v_po_id;
end;
$$;

-- @seq 407
CREATE FUNCTION public.erp__default_location(p_tenant_id uuid, p_warehouse_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(
    (SELECT l.id FROM erp_warehouse_locations l WHERE l.tenant_id = p_tenant_id AND l.warehouse_id = p_warehouse_id
        AND l.id::text = nullif(current_setting('app.erp_location_id', true), '')),
    (SELECT l.id FROM erp_warehouse_locations l WHERE l.tenant_id = p_tenant_id AND l.warehouse_id = p_warehouse_id
        AND coalesce(l.is_active, true)
      ORDER BY coalesce(l.is_receiving, false) DESC, coalesce(l.is_pickable, false) DESC, l.code LIMIT 1));
$$;

-- @seq 408
CREATE FUNCTION public.erp__default_warehouse(p_tenant_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(
    (SELECT w.id FROM erp_warehouses w WHERE w.tenant_id = p_tenant_id
        AND w.id::text = nullif(current_setting('app.erp_warehouse_id', true), '')),
    (SELECT w.id FROM erp_warehouses w WHERE w.tenant_id = p_tenant_id AND coalesce(w.is_active, true)
      ORDER BY w.created_at, w.code LIMIT 1));
$$;

-- @seq 409
CREATE FUNCTION public.erp__move(p_tenant_id uuid, p_type text, p_sku uuid, p_wh uuid, p_loc uuid, p_qty numeric, p_unit_cost numeric, p_source_type text, p_source_id uuid, p_reference text, p_reason text, p_meta jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v uuid; v_cost numeric;
BEGIN
  -- unit cost: given, else the SKU standard cost, else 0 (the ledger's FIFO/average cost lives in acct_inventory_layers)
  v_cost := coalesce(p_unit_cost, (SELECT standard_cost FROM erp_product_skus WHERE id = p_sku), 0);
  INSERT INTO erp_inventory_movements(tenant_id, movement_type, sku_id, warehouse_id, from_location_id, to_location_id, quantity,
         unit_cost, total_cost, source_type, source_id, reference, reason, metadata, performed_by, occurred_at)
  VALUES (p_tenant_id, p_type::erp_inventory_movement_type, p_sku, p_wh, CASE WHEN p_qty < 0 THEN p_loc END, CASE WHEN p_qty >= 0 THEN p_loc END,
          p_qty, v_cost, round(p_qty * v_cost, 2), p_source_type, p_source_id::text, p_reference, p_reason,
          coalesce(p_meta,'{}'::jsonb), auth.uid(), now())
  RETURNING id INTO v;
  RETURN v;
END $$;

-- @seq 411
CREATE FUNCTION public.erp__sku_for_item(p_item_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(i.sku_id,
           (SELECT s.id FROM erp_product_skus s WHERE s.tenant_id = i.tenant_id
               AND i.product_variant_id IS NOT NULL
               AND (s.catalog_variant_id = i.product_variant_id OR s.variant_id = i.product_variant_id)
             ORDER BY s.created_at LIMIT 1))
    FROM acct_items i WHERE i.id = p_item_id;
$$;

-- @seq 412
CREATE FUNCTION public.erp__sku_for_variant(p_tenant_id uuid, p_variant_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT s.id FROM erp_product_skus s
   WHERE s.tenant_id = p_tenant_id AND (s.catalog_variant_id = p_variant_id OR s.variant_id = p_variant_id OR s.id = p_variant_id)
   ORDER BY (s.catalog_variant_id = p_variant_id) DESC, s.created_at LIMIT 1;
$$;

-- @seq 414
CREATE FUNCTION public.erp_adjust_stock(p_sku_id uuid, p_qty_change numeric, p_reason text, p_warehouse_id uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_date date DEFAULT CURRENT_DATE, p_unit_cost numeric DEFAULT NULL::numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE s erp_product_skus%ROWTYPE; v_item uuid; v_wh uuid; v_loc uuid; v_move uuid;
BEGIN
  SELECT * INTO s FROM erp_product_skus WHERE id = p_sku_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'SKU not found'; END IF;
  PERFORM acct_assert_access(s.tenant_id);
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN RAISE EXCEPTION 'A reason is required for stock adjustments'; END IF;
  IF p_qty_change = 0 THEN RETURN NULL; END IF;
  v_wh := coalesce(p_warehouse_id, erp__default_warehouse(s.tenant_id));
  IF v_wh IS NULL THEN RAISE EXCEPTION 'Set up a warehouse first'; END IF;
  v_loc := coalesce(p_location_id, erp__default_location(s.tenant_id, v_wh));
  SELECT i.id INTO v_item FROM acct_items i WHERE i.tenant_id = s.tenant_id AND i.item_type = 'inventory'
     AND (i.sku_id = s.id OR (i.product_variant_id IS NOT NULL AND i.product_variant_id IN (s.catalog_variant_id, s.variant_id))) LIMIT 1;
  IF v_item IS NOT NULL THEN
    PERFORM set_config('app.erp_warehouse_id', v_wh::text, true);
    PERFORM set_config('app.erp_location_id', coalesce(v_loc::text,''), true);
    PERFORM acct_inventory_adjust(v_item, p_qty_change, p_date, p_reason, p_unit_cost, NULL, 'ADJ');
    PERFORM set_config('app.erp_warehouse_id', '', true);
    PERFORM set_config('app.erp_location_id', '', true);
    SELECT erp_movement_id INTO v_move FROM acct_inventory_moves WHERE item_id = v_item ORDER BY created_at DESC LIMIT 1;
  ELSE
    v_move := erp__move(s.tenant_id, 'adjustment', s.id, v_wh, v_loc, p_qty_change, coalesce(p_unit_cost, s.standard_cost), 'adjustment', NULL, 'ADJ', p_reason);
  END IF;
  RETURN v_move;
END $$;

-- @seq 419
CREATE FUNCTION public.erp_movement_stock_trg() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_delta numeric; v_res numeric := 0;
BEGIN
  IF NEW.warehouse_id IS NULL OR coalesce(NEW.metadata->>'affects_stock', 'true') = 'false' THEN RETURN NEW; END IF;
  IF NEW.movement_type IN ('reservation','reservation_release','allocation','deallocation','pick','unpick','pack','unpack') THEN
    -- workflow states, not stock changes; reservations adjust the reserved column
    IF NEW.movement_type IN ('reservation','reservation_release') THEN
      v_res := CASE WHEN NEW.movement_type = 'reservation' THEN abs(NEW.quantity) ELSE -abs(NEW.quantity) END;
    ELSE
      RETURN NEW;
    END IF;
    v_delta := 0;
  ELSE
    v_delta := NEW.quantity;
  END IF;
  INSERT INTO erp_stock_levels(tenant_id, sku_id, warehouse_id, location_id, on_hand, reserved, allocated)
  VALUES (NEW.tenant_id, NEW.sku_id, NEW.warehouse_id, coalesce(NEW.to_location_id, NEW.from_location_id), v_delta, greatest(v_res,0), 0)
  ON CONFLICT (tenant_id, sku_id, warehouse_id, coalesce(location_id, '00000000-0000-0000-0000-000000000000'::uuid))
  DO UPDATE SET on_hand = coalesce(erp_stock_levels.on_hand,0) + v_delta,
                reserved = greatest(coalesce(erp_stock_levels.reserved,0) + v_res, 0);
  RETURN NEW;
END $$;

-- @seq 423
CREATE FUNCTION public.erp_rebuild_stock_balances(p_tenant uuid, p_sku uuid DEFAULT NULL::uuid, p_warehouse_id uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count integer;
BEGIN
  DELETE FROM public.erp_inventory_balances b
   WHERE b.tenant_id = p_tenant
     AND (p_sku IS NULL OR b.sku_id = p_sku)
     AND (p_warehouse_id IS NULL OR b.warehouse_id = p_warehouse_id);

  INSERT INTO public.erp_inventory_balances
    (id, tenant_id, sku_id, warehouse_id, location_id, inventory_status,
     on_hand, reserved, allocated, picked, packed, in_transit,
     unit_cost, bin_location, created_at, updated_at)
  SELECT gen_random_uuid(), sl.tenant_id, sl.sku_id, sl.warehouse_id,
         sl.location_id, 'available'::public.erp_inventory_status,
         sl.on_hand, sl.reserved, sl.allocated, 0, 0, 0,
         COALESCE(s.standard_cost, 0), loc.code, now(), now()
    FROM public.erp_stock_levels sl
    JOIN public.erp_product_skus s
      ON s.id = sl.sku_id AND s.tenant_id = sl.tenant_id
    LEFT JOIN public.erp_warehouse_locations loc
      ON loc.id = sl.location_id AND loc.tenant_id = sl.tenant_id
   WHERE sl.tenant_id = p_tenant
     AND sl.location_id IS NOT NULL
     AND (p_sku IS NULL OR sl.sku_id = p_sku)
     AND (p_warehouse_id IS NULL OR sl.warehouse_id = p_warehouse_id);

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;

-- @seq 424
CREATE FUNCTION public.erp_receive_purchase_order(p_po_id uuid, p_lines jsonb DEFAULT NULL::jsonb, p_warehouse_id uuid DEFAULT NULL::uuid, p_received_at timestamp with time zone DEFAULT now(), p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE po erp_purchase_orders%ROWTYPE; v_wh uuid; v_rec uuid; l record; v_qty numeric; v_open numeric; v_loc uuid; x jsonb; v_any boolean := false;
BEGIN
  SELECT * INTO po FROM erp_purchase_orders WHERE id = p_po_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase order not found'; END IF;
  PERFORM acct_assert_access(po.tenant_id);
  IF lower(coalesce(po.status,'draft')) IN ('cancelled','closed') THEN RAISE EXCEPTION 'Purchase order is %', po.status; END IF;
  v_wh := coalesce(p_warehouse_id, po.warehouse_id, erp__default_warehouse(po.tenant_id));
  IF v_wh IS NULL THEN RAISE EXCEPTION 'Set up a warehouse before receiving stock'; END IF;
  INSERT INTO erp_goods_receipts(tenant_id, receipt_number, purchase_order_id, warehouse_id, status, received_at, received_by, notes)
  VALUES (po.tenant_id, erp_next_document_number(po.tenant_id, 'goods_receipt'), po.id, v_wh, 'received', p_received_at, auth.uid(), p_notes)
  RETURNING id INTO v_rec;
  FOR l IN SELECT * FROM erp_purchase_order_lines WHERE purchase_order_id = po.id ORDER BY created_at LOOP
    v_open := coalesce(l.quantity_ordered, l.quantity) - coalesce(l.quantity_received, 0);
    x := CASE WHEN p_lines IS NULL THEN NULL ELSE (SELECT e FROM jsonb_array_elements(p_lines) e WHERE (e->>'po_line_id')::uuid = l.id LIMIT 1) END;
    v_qty := CASE WHEN p_lines IS NULL THEN v_open ELSE coalesce((x->>'quantity')::numeric, 0) END;
    CONTINUE WHEN v_qty <= 0;
    IF v_qty > v_open THEN RAISE EXCEPTION 'Line % has only % open to receive', coalesce(l.description, l.id::text), v_open; END IF;
    IF l.sku_id IS NULL THEN RAISE EXCEPTION 'Line % has no SKU; add the SKU before receiving', coalesce(l.description, l.id::text); END IF;
    v_loc := coalesce(nullif(x->>'location_id','')::uuid, erp__default_location(po.tenant_id, v_wh));
    IF v_loc IS NULL THEN RAISE EXCEPTION 'Warehouse has no locations; add a receiving location'; END IF;
    INSERT INTO erp_goods_receipt_lines(tenant_id, receipt_id, purchase_order_line_id, sku_id, location_id, lot_id, quantity_received, unit_cost)
    VALUES (po.tenant_id, v_rec, l.id, l.sku_id, v_loc, nullif(x->>'lot_id','')::uuid, v_qty, coalesce((x->>'unit_cost')::numeric, l.unit_cost));
    UPDATE erp_purchase_order_lines SET quantity_received = coalesce(quantity_received,0) + v_qty WHERE id = l.id;
    PERFORM erp__move(po.tenant_id, 'purchase_receipt', l.sku_id, v_wh, v_loc, v_qty, coalesce((x->>'unit_cost')::numeric, l.unit_cost),
                      'erp_goods_receipts', v_rec, po.po_number, 'PO receipt');
    v_any := true;
  END LOOP;
  IF NOT v_any THEN RAISE EXCEPTION 'Nothing left to receive on PO %', po.po_number; END IF;
  UPDATE erp_purchase_orders SET
         status = CASE WHEN NOT EXISTS (SELECT 1 FROM erp_purchase_order_lines WHERE purchase_order_id = po.id
                                          AND coalesce(quantity_received,0) < coalesce(quantity_ordered, quantity)) THEN 'received' ELSE 'partially_received' END,
         received_at = CASE WHEN received_at IS NULL THEN p_received_at ELSE received_at END, updated_at = now()
   WHERE id = po.id;
  RETURN v_rec;
END $$;

-- @seq 426
CREATE FUNCTION public.erp_receive_transfer(p_transfer_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE t erp_inventory_transfers%ROWTYPE; l record;
BEGIN
  SELECT * INTO t FROM erp_inventory_transfers WHERE id = p_transfer_id FOR UPDATE;
  PERFORM acct_assert_access(t.tenant_id);
  IF t.status <> 'in_transit' THEN RAISE EXCEPTION 'Transfer is %', t.status; END IF;
  FOR l IN SELECT * FROM erp_inventory_transfer_lines WHERE transfer_id = t.id LOOP
    PERFORM erp__move(t.tenant_id, 'transfer', l.sku_id, t.to_warehouse_id, erp__default_location(t.tenant_id, t.to_warehouse_id),
                      l.shipped_quantity - coalesce(l.received_quantity,0), NULL, 'erp_inventory_transfers', t.id, t.transfer_number, 'Transfer in');
    UPDATE erp_inventory_transfer_lines SET received_quantity = shipped_quantity WHERE id = l.id;
  END LOOP;
  UPDATE erp_inventory_transfers SET status = 'received', received_at = now(), updated_at = now() WHERE id = t.id;
END $$;

-- @seq 429
CREATE FUNCTION public.erp_send_purchase_order(p_po_id uuid, p_to text DEFAULT NULL::text, p_message text DEFAULT NULL::text, p_document_url text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE po erp_purchase_orders%ROWTYPE; v_to text; v_name text; v_mail uuid;
BEGIN
  SELECT * INTO po FROM erp_purchase_orders WHERE id = p_po_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Purchase order not found'; END IF;
  PERFORM acct_assert_access(po.tenant_id);
  IF lower(coalesce(po.status,'draft')) IN ('cancelled','closed','received') THEN RAISE EXCEPTION 'Purchase order is %', po.status; END IF;
  IF NOT EXISTS (SELECT 1 FROM erp_purchase_order_lines WHERE purchase_order_id = po.id) THEN RAISE EXCEPTION 'Add at least one line before sending'; END IF;
  SELECT coalesce(p_to, v.email), coalesce(v.display_name, v.legal_name) INTO v_to, v_name FROM acct_vendors v WHERE v.id = po.vendor_id;
  IF v_to IS NULL THEN RAISE EXCEPTION 'Vendor has no email address; pass one or add it to the vendor'; END IF;
  v_mail := email_enqueue(po.tenant_id, 'po-send:' || po.id || ':' || coalesce(po.updated_at, po.created_at)::text, app__default_from(po.tenant_id), ARRAY[v_to],
              'Purchase order ' || po.po_number,
              '<p>' || coalesce(p_message, 'Please find our purchase order ' || po.po_number || ' attached.') || '</p>'
              || coalesce('<p><a href="' || p_document_url || '">View purchase order</a></p>', ''),
              NULL, 'transactional', 'erp_purchase_orders', po.id,
              CASE WHEN p_document_url IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(jsonb_build_object('path', p_document_url, 'filename', po.po_number || '.pdf')) END);
  UPDATE erp_purchase_orders SET status = CASE WHEN lower(coalesce(status,'draft')) IN ('draft','approved','pending') THEN 'sent' ELSE status END, updated_at = now()
   WHERE id = po.id;
  RETURN v_mail;
END $$;

-- @seq 432
CREATE FUNCTION public.erp_stock_history(p_sku_id uuid, p_from date DEFAULT NULL::date, p_to date DEFAULT CURRENT_DATE) RETURNS TABLE(occurred_at timestamp with time zone, movement_type text, warehouse text, quantity numeric, running_on_hand numeric, unit_cost numeric, source_type text, reference text, reason text, affects_stock boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_t uuid;
BEGIN
  SELECT tenant_id INTO v_t FROM erp_product_skus WHERE id = p_sku_id;
  PERFORM acct_assert_access(v_t);
  RETURN QUERY
  SELECT m.occurred_at, m.movement_type::text, w.name::text, m.quantity,
         sum(CASE WHEN m.warehouse_id IS NOT NULL AND coalesce(m.metadata->>'affects_stock','true') <> 'false'
                   AND m.movement_type::text NOT IN ('reservation','reservation_release','allocation','deallocation','pick','unpick','pack','unpack')
                  THEN m.quantity ELSE 0 END) OVER (ORDER BY m.occurred_at, m.created_at),
         m.unit_cost, m.source_type, m.reference, m.reason, coalesce(m.metadata->>'affects_stock','true') <> 'false'
    FROM erp_inventory_movements m LEFT JOIN erp_warehouses w ON w.id = m.warehouse_id
   WHERE m.sku_id = p_sku_id AND m.tenant_id = v_t
     AND (p_from IS NULL OR m.occurred_at::date >= p_from) AND m.occurred_at::date <= p_to
   ORDER BY m.occurred_at, m.created_at;
END $$;

-- @seq 433
CREATE FUNCTION public.erp_transfer_stock(p_tenant_id uuid, p_from_warehouse uuid, p_to_warehouse uuid, p_lines jsonb, p_receive_now boolean DEFAULT true, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_tr uuid; x jsonb; v_from_loc uuid; v_to_loc uuid; v_oh numeric;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  IF p_from_warehouse = p_to_warehouse THEN RAISE EXCEPTION 'Pick two different warehouses'; END IF;
  IF (SELECT count(*) FROM erp_warehouses WHERE tenant_id = p_tenant_id AND id IN (p_from_warehouse, p_to_warehouse)) <> 2 THEN
    RAISE EXCEPTION 'Both warehouses must belong to this company';
  END IF;
  IF p_lines IS NULL OR jsonb_array_length(p_lines) = 0 THEN RAISE EXCEPTION 'Add at least one SKU to transfer'; END IF;
  INSERT INTO erp_inventory_transfers(tenant_id, transfer_number, from_warehouse_id, to_warehouse_id, status, requested_at, shipped_at, received_at, notes, created_by)
  VALUES (p_tenant_id, erp_next_document_number(p_tenant_id, 'transfer'), p_from_warehouse, p_to_warehouse,
          CASE WHEN p_receive_now THEN 'received' ELSE 'in_transit' END, now(), now(), CASE WHEN p_receive_now THEN now() END, p_notes, auth.uid())
  RETURNING id INTO v_tr;
  v_from_loc := erp__default_location(p_tenant_id, p_from_warehouse);
  v_to_loc := erp__default_location(p_tenant_id, p_to_warehouse);
  FOR x IN SELECT value FROM jsonb_array_elements(p_lines) LOOP
    IF coalesce((x->>'quantity')::numeric, 0) <= 0 THEN RAISE EXCEPTION 'Transfer quantities must be positive'; END IF;
    SELECT coalesce(sum(on_hand),0) INTO v_oh FROM erp_stock_levels WHERE tenant_id = p_tenant_id AND sku_id = (x->>'sku_id')::uuid AND warehouse_id = p_from_warehouse;
    IF v_oh < (x->>'quantity')::numeric THEN RAISE EXCEPTION 'Only % on hand in the source warehouse for SKU %', v_oh, x->>'sku_id'; END IF;
    INSERT INTO erp_inventory_transfer_lines(tenant_id, transfer_id, sku_id, quantity, shipped_quantity, received_quantity)
    VALUES (p_tenant_id, v_tr, (x->>'sku_id')::uuid, (x->>'quantity')::numeric, (x->>'quantity')::numeric, CASE WHEN p_receive_now THEN (x->>'quantity')::numeric ELSE 0 END);
    PERFORM erp__move(p_tenant_id, 'transfer', (x->>'sku_id')::uuid, p_from_warehouse, v_from_loc, -(x->>'quantity')::numeric, NULL, 'erp_inventory_transfers', v_tr, NULL, 'Transfer out');
    IF p_receive_now THEN
      PERFORM erp__move(p_tenant_id, 'transfer', (x->>'sku_id')::uuid, p_to_warehouse, v_to_loc, (x->>'quantity')::numeric, NULL, 'erp_inventory_transfers', v_tr, NULL, 'Transfer in');
    END IF;
  END LOOP;
  RETURN v_tr;
END $$;

-- @seq 442
CREATE FUNCTION public.is_consumable_type(t text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT t IS NOT NULL
    AND t !~* '\m(toys?|beds?|bowls?|dishes|apparel|collars?|leads?|harness|decor|filters?|pumps?|tools|travel|crates?|cratemats|bedding|substrates?|light|poop)\M'
    AND t ~* '\m(food|treats?|supplements?|flea|tick|litter|topper|water care|vitamins?)\M'
$$;

-- @seq 606
CREATE FUNCTION public.trg_goods_receipt_line() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE l purchase_order_lines%ROWTYPE; r goods_receipts%ROWTYPE; po purchase_orders%ROWTYPE;
BEGIN
  SELECT * INTO r FROM goods_receipts WHERE id = NEW.goods_receipt_id;
  SELECT * INTO l FROM purchase_order_lines WHERE id = NEW.po_line_id FOR UPDATE;
  IF l.purchase_order_id <> r.purchase_order_id THEN
    RAISE EXCEPTION 'Receipt line belongs to a different purchase order';
  END IF;
  SELECT * INTO po FROM purchase_orders WHERE id = l.purchase_order_id;
  IF po.status NOT IN ('approved','partially_received') THEN
    RAISE EXCEPTION 'PO % must be approved before receiving (status %)', po.po_number, po.status;
  END IF;
  IF l.qty_received + NEW.qty_received > l.qty_ordered THEN
    RAISE EXCEPTION 'Over-receipt on PO % line %: ordered %, already received %, receiving %',
      po.po_number, l.line_no, l.qty_ordered, l.qty_received, NEW.qty_received;
  END IF;

  UPDATE purchase_order_lines SET qty_received = qty_received + NEW.qty_received WHERE id = l.id;

  IF l.variant_id IS NOT NULL THEN
    INSERT INTO inventory_levels (location_id, variant_id, seller_id, on_hand)
    VALUES (r.location_id, l.variant_id, first_party_seller(po.tenant_id), NEW.qty_received)
    ON CONFLICT (location_id, variant_id, seller_id)
      DO UPDATE SET on_hand = inventory_levels.on_hand + EXCLUDED.on_hand;
  END IF;

  UPDATE purchase_orders
     SET status = CASE WHEN NOT EXISTS (SELECT 1 FROM purchase_order_lines
                                         WHERE purchase_order_id = po.id AND qty_received < qty_ordered)
                       THEN 'received' ELSE 'partially_received' END
   WHERE id = po.id;
  RETURN NEW;
END $$;

-- @seq 608
CREATE FUNCTION public.trg_po_revoke() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.status IN ('approved','partially_received','received','closed')
     AND NEW.status NOT IN ('approved','partially_received','received','closed') THEN
    PERFORM revalidate_brand(NEW.brand_id);
  END IF;
  RETURN NEW;
END $$;

-- @seq 609
CREATE FUNCTION public.trg_po_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND NEW.status = 'approved' AND OLD.status <> 'approved' AND NEW.approved_at IS NULL THEN
    NEW.approved_at := now();
  END IF;
  RETURN NEW;
END $$;

